-- 353 locais e 1072 avaliações ESTIMADAS (não vêm de usuárias do GoSafe). Fontes: carga-inicial/fontes.csv






















-- Mesma conta do PlaceRatingService: média ponderada, arredondada em 2 casas
UPDATE places p
SET weighted_rating = s.rating, rating_count = s.total
FROM (
    SELECT place_id,
           round((sum(score * applied_weight) / sum(applied_weight))::numeric, 2)::double precision AS rating,
           count(*)::integer AS total
    FROM reviews
    GROUP BY place_id
) s
WHERE p.id = s.place_id AND p.created_by = '596de9d2-90db-5436-bac1-f89459a16617';
